{
  "passageId": "dopamine-motor-control",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "도파민을 외부에서 섭취할 수 있지만 뇌로 유입될 수는 없다는 한계를 제시하므로 양보·한계 관계이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 도파민이 혈액-뇌 장벽을 통과하지 못한다는 사실로부터 뇌의 신경 경로를 이동할 수 있는 도파민의 출처를 한정한다."
    },
    {
      "id": "R3",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 도파민의 장벽 통과 불가능성이 뇌에서 신경 전달 물질로 작용하는 도파민의 출처에 관한 판단을 뒷받침한다."
    },
    {
      "id": "R4",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "신호 전달에서 맡는 역할을 기준으로 시냅스 전 뉴런의 전달 기능과 시냅스 후 뉴런의 수용 기능을 대비한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "신경 전달 물질의 일반적인 신호 전달을 그 한 사례인 도파민의 저장·분비·결합 과정으로 구체화한다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "티로신이 뉴런에 흡수된 다음 레보도파로 합성되는 단계의 차례를 제시한다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "티로신에서 레보도파가 합성된 다음 레보도파에서 도파민이 합성되는 순서를 설명한다."
    },
    {
      "id": "R8",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민의 합성에 이어 저장·분비·수용체 결합이 진행되는 후속 단계를 제시한다."
    },
    {
      "id": "R9",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민이 시냅스 소포에 저장되었다가 뉴런 활성화 시 분비되는 시간적 순서를 나타낸다."
    },
    {
      "id": "R10",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민의 시냅스 틈 분비에 이어 시냅스 후 뉴런의 수용체 결합이 진행되는 순서를 나타낸다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "도파민의 수용체 결합이 실제로 시냅스 후 뉴런으로의 신호 전달을 일으킨다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞에서 언급한 도파민 수용체를 두 계열과 각각의 작용으로 나누어 자세히 설명한다."
    },
    {
      "id": "R13",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "신호 전달 활성에 미치는 영향을 기준으로 D1의 흥분성 작용과 D2의 억제성 작용을 대비한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D2 계열 수용체의 억제성 작용 원리를 도파민성 뉴런의 자가 수용체에 적용한다."
    },
    {
      "id": "R15",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "도파민성 뉴런에 위치한 D2 계열 수용체에 자가 수용체라는 이름을 붙인다."
    },
    {
      "id": "R16",
      "type": "CAUSE",
      "otherName": "",
      "reason": "자가 수용체 결합에 따른 신호 전달 활성 억제가 실제로 도파민 분비 중단을 일으킨다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "분비된 도파민이 자기 뉴런의 분비를 중단시키는 기제로부터 분비의 자기 조절이 가능하다는 판단을 도출한다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "분비된 도파민이 자가 수용체에 결합하여 이후의 도파민 분비를 억제하는 되먹임 작용으로 이어진다."
    },
    {
      "id": "R19",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "분비된 도파민의 수용체 결합을 설명한 뒤 일부는 결합하지 않고 재흡수된다는 예외를 제시한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "DAT가 도파민성 뉴런에 위치한다는 사실은 DAT를 통해 도파민이 그 뉴런으로 재흡수되는 경로를 설명하는 근거이다."
    },
    {
      "id": "R21",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민이 재흡수된 다음 시냅스 소포에 저장되고 재사용되는 후속 순서를 제시한다."
    },
    {
      "id": "R22",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민의 재흡수 이후 뉴런 안에서 효소에 의해 분해되는 후속 과정을 제시한다."
    },
    {
      "id": "R23",
      "type": "CONDITION",
      "otherName": "",
      "reason": "재흡수된 도파민의 후속 처리가 재사용되는 경우와 뉴런 안에서 분해되는 경우로 갈린다."
    },
    {
      "id": "R24",
      "type": "CONDITION",
      "otherName": "",
      "reason": "DAT가 없는 뉴런이라는 경우를 구분하여 그 뉴런에서 분비된 도파민의 분해 장소를 설명한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "DAT를 통한 재흡수와 처리를 설명한 뒤 모든 뉴런에 DAT가 있는 것은 아니라는 적용상의 한계를 제시한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도파민이 관여하는 여러 기능 중 운동 조절을 수의적 운동의 조절로 좁혀 구체화한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 신경 경로의 상호 보완적 조절이라는 설명을 직접 경로의 구체적인 작동으로 풀어 준다."
    },
    {
      "id": "R28",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 신경 경로의 상호 보완적 조절이라는 설명을 간접 경로의 구체적인 작동으로 풀어 준다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "선조체 뉴런이 가바성 뉴런이라는 사실이 활성화 시 가바를 분비한다는 설명을 뒷받침한다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "선조체에서 내측 창백핵으로 분비된 가바가 내측 창백핵 뉴런의 활성을 억제한다."
    },
    {
      "id": "R31",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내측 창백핵 뉴런의 활성 억제가 시상으로의 가바 분비 중단을 일으킨다."
    },
    {
      "id": "R32",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "내측 창백핵 뉴런이 가바성이라는 사실은 그 뉴런의 활성 억제를 가바 분비 중단으로 설명하는 근거이다."
    },
    {
      "id": "R33",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상으로 가바가 분비되지 않는 것이 시상 뉴런의 억제를 풀어 활성화를 일으킨다."
    },
    {
      "id": "R34",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상의 글루타메이트성 뉴런 활성화가 대뇌 피질 운동 영역으로의 글루타메이트 분비를 일으킨다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "대뇌 피질 운동 영역으로의 글루타메이트 분비가 실제 운동 시작으로 이어진다."
    },
    {
      "id": "R36",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "선조체와 내측 창백핵의 연결 방식을 기준으로 직접 연결과 다른 부위를 거치는 간접 연결을 대비한다."
    },
    {
      "id": "R37",
      "type": "CAUSE",
      "otherName": "",
      "reason": "간접 경로에서 내측 창백핵으로 분비된 글루타메이트가 내측 창백핵 뉴런을 활성화한다."
    },
    {
      "id": "R38",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내측 창백핵 뉴런의 활성화가 직접 경로와 반대되는 후속 작용을 일으키는 기점으로 설명된다."
    },
    {
      "id": "R39",
      "type": "CAUSE",
      "otherName": "",
      "reason": "간접 경로에서 일어나는 직접 경로와 상반된 작용이 운동 차단을 일으킨다."
    },
    {
      "id": "R40",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "운동에 미치는 효과를 기준으로 직접 경로의 운동 시작과 간접 경로의 운동 차단을 대비한다."
    },
    {
      "id": "R41",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "직접·간접 경로 자체의 운동 조절 기제에서 도파민이 두 경로에 미치는 영향으로 논의를 옮긴다."
    },
    {
      "id": "R42",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "흑질의 도파민성 뉴런이 선조체에 연결된다는 해부학적 사실이 두 경로를 통한 운동 조절의 설명을 뒷받침한다."
    },
    {
      "id": "R43",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D1 계열 수용체의 흥분성 작용 원리를 직접 경로에 대한 도파민의 작용에 적용한다."
    },
    {
      "id": "R44",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로에 D1 계열 수용체가 밀집한다는 사실이 도파민에 의한 직접 경로 활성화를 설명하는 근거이다."
    },
    {
      "id": "R45",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D2 계열 수용체의 억제성 작용 원리를 간접 경로에 대한 도파민의 작용에 적용한다."
    },
    {
      "id": "R46",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로에 D2 계열 수용체가 밀집한다는 사실이 도파민에 의한 간접 경로 억제를 설명하는 근거이다."
    },
    {
      "id": "R47",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "도파민의 작용을 받는 경로를 기준으로 직접 경로의 활성화와 간접 경로의 억제를 대비한다."
    },
    {
      "id": "R48",
      "type": "CAUSE",
      "otherName": "",
      "reason": "운동을 시작시키는 직접 경로의 활성화가 목표 운동의 시작을 수월하게 하는 실제 효과로 이어진다."
    },
    {
      "id": "R49",
      "type": "CAUSE",
      "otherName": "",
      "reason": "운동을 차단하는 간접 경로의 억제가 목표 운동의 시작을 수월하게 하는 실제 효과로 이어진다."
    },
    {
      "id": "R50",
      "type": "CAUSE",
      "otherName": "",
      "reason": "목표 운동의 시작이 수월해지는 것이 운동 촉진이라는 실제 효과로 이어진다."
    },
    {
      "id": "R51",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로가 운동을 시작시킨다는 설명이 그 경로의 활성화가 운동 시작을 돕는다는 판단을 뒷받침한다."
    },
    {
      "id": "R52",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로가 운동을 차단한다는 설명이 그 경로의 억제가 운동 시작을 돕는다는 판단을 뒷받침한다."
    }
  ]
}

